          ...state,
          oldCart: null,
        };
      let brands = [];
      let products = payload.oldCart ?? [];

      let oldCart = products.map((product) => ({
        ...product,
        offer_price: product.discount
          ? product.price_of_variant - product.discount
          : 0,
