          transform="translate(-0.48 7.188)"
          fill="#8d8d8d"
        />
      </svg>
    );
  };
  const MinusIcon = ({ className }) => {
    return (
      <svg
        className={"hide-btn"}
        xmlns="http://www.w3.org/2000/svg"
        width="12"
        height="2.548"
        viewBox="0 0 12 2.548"
      >
        <path
          className="hide-btn"
          id="Path_22217"
          data-name="Path 22217"
          d="M1.775.295A1.254,1.254,0,0,1,.85-.076,1.259,1.259,0,0,1,.48-1a1.183,1.183,0,0,1,.37-.9,1.3,1.3,0,0,1,.925-.347h9.41a1.275,1.275,0,0,1,.925.359,1.22,1.22,0,0,1,.37.915,1.22,1.22,0,0,1-.37.915,1.275,1.275,0,0,1-.925.359Z"
          transform="translate(-0.48 2.254)"
          fill="#8d8d8d"
        />
      </svg>
    );
  };
  const DeleteIcon = () => {
    return (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        width="9.746"
        height="12"
        viewBox="0 0 9.746 12"
      >
        <path
          id="Path_14712"
          data-name="Path 14712"
          d="M.795,3.571V10.5a1.55,1.55,0,0,0,.412,1.069,1.384,1.384,0,0,0,1,.434H7.528a1.384,1.384,0,0,0,1-.434A1.55,1.55,0,0,0,8.945,10.5V3.571A1.074,1.074,0,0,0,8.669,1.46H7.231V1.109A1.1,1.1,0,0,0,6.118,0h-2.5a1.1,1.1,0,0,0-1.113,1.11V1.46H1.07A1.074,1.074,0,0,0,.795,3.571Zm6.734,7.865H2.211a.89.89,0,0,1-.854-.941V3.6H8.383v6.9A.89.89,0,0,1,7.528,11.437ZM3.071,1.109A.541.541,0,0,1,3.622.561h2.5a.541.541,0,0,1,.551.548V1.46h-3.6Zm-2,.913h7.6a.506.506,0,1,1,0,1.012H1.07a.506.506,0,1,1,0-1.012Zm0,0"
          transform="translate(0.003 0.001)"
          fill="#ff5f61"
        />
      </svg>
    );
  };
  const dispatch = useDispatch();
  const updateQuantity = async (quantity, bool) => {
    let dataBody = [];
    let dataObj = { key: id, quantity: quantity };
    for (var property in dataObj) {
      if (dataObj[property] || dataObj[property] === 0) {
        var encodedKey = encodeURIComponent(property);
        var encodedValue = encodeURIComponent(dataObj[property]);
        dataBody.push(encodedKey + "=" + encodedValue);
      }
    }
    // @ts-ignore
    dataBody = dataBody.join("&");
    try {
      await AxiosPost({
        url: process.env.NEXT_PUBLIC_BACKEND_URL + "/cart/update",
        title: "Update Quantity For Product In cart",
        body: dataBody,
      });
      dispatch({
        type: "UPDATE-CART-QUANTITY",
        payload: { key: id, quantity: quantity },
      });
    } catch (error) {
      if (bool) {
        setInputValue(inputValue);
      } else {
        setInputValue(inputValue);
      }
    }
  };
  const decimal_point_settings = useSelector(
    (state: StateInterface) => state.homepage.settings
  );
  let { lang } = useParams();
  // @ts-ignore
  let languageVariable = lang.split("-")[1];
  const translate = (key: string, lang?: string) => {
    return translateFunction(key, languageVariable);
  };
  const currency = useSelector(
    (state: StateInterface) => state.homepage.currency
  ) || { exchange_rate: 1, symbol: "" };
  const decreaseQuantity = async (i) => {
    if (!loading) {
      setInputValue(parseInt(i) - 1);
      setLoading(true);

      await updateQuantity(parseInt(i.toString()) - 1, false);
      await getCart({
        callback: ([data, res]) => {
          dispatch({ type: "CART-INIT", payload: data });
        },
      });
      setLoading(false);
    }
  };
  const [loading, setLoading] = useState(false);
  const increaseQuantity = async (i) => {
    if (!loading) {
      setInputValue(parseInt(i.toString()) + 1);
      setLoading(true);
      await updateQuantity(parseInt(i.toString()) + 1, true);
      await getCart({
        callback: ([data, res]) => {
          dispatch({ type: "CART-INIT", payload: data });
        },
      });
      setLoading(false);
    }
  };
  return (
    <div
      className={`absolute flex-wrap ${"top-[115px]"} left-[137px] flex-row items-center justify-between max-w-[calc(100%-152px)] w-full`}
    >
      <div
        className={`${
          loading && "opacity-40"
        } flex-row hide-btn relative max-w-[72px] w-[72px] h-[24px] mt-4 z-50`}
      >
        <svg
          className="absolute hide-btn"
          xmlns="http://www.w3.org/2000/svg"
          width="72"
          height="24"
          viewBox="0 0 72 24"
        >
          <g
            id="Group_12755"
            data-name="Group 12755"
            transform="translate(-140 -277)"
          >
            <g
              id="Rectangle_5745"
              data-name="Rectangle 5745"
              transform="translate(140 277)"
              fill="none"
              stroke="#d3d3d3"
              strokeWidth="0.5"
            >
              <rect width="72" height="24" rx="5" stroke="none" />
              <rect
                x="0.25"
                y="0.25"
                width="71.5"
                height="23.5"
                rx="4.75"
                fill="none"
              />
            </g>
          </g>
        </svg>
        <div
          className="absolute hide-btn h-[24px] flex items-center right-[6px]  cursor-pointer"
          data-cy="PlusIcon_CartPage"
          onClick={() => {
            if (disabled) return false;
            if (inputValue === max) {
              toast.error(translate("stock is limited"));
              return false;
            }
            // @ts-ignore
            else {
              increaseQuantity(inputValue);
            }
          }}
        >
          <PlusIcon className="" />
        </div>

        {inputValue > 1 ? (
          <div
            className="absolute h-[24px] flex items-center hide-btn left-[6px]  cursor-pointer"
            data-cy="MinusIcon_CartPage"
            onClick={() => {
              if (disabled) return false;
              if (inputValue > 1) {
                // @ts-ignore

                decreaseQuantity(inputValue);
              }
            }}
          >
            <MinusIcon className="" />
          </div>
        ) : (
          <div
            className="absolute h-[24px] flex items-center hide-btn left-[6px]  cursor-pointer"
            data-cy="DeleteIcon_CartPage"
            onClick={() => {
              deleteFunction();
            }}
          >
            <DeleteIcon />
          </div>
        )}
        <input
          // @ts-ignore
          value={parseInt(inputValue)}
          data-cy="QuantityInCart"
          max={max}
          disabled
          onChange={(e) => {}}
          className="outline-none hide-btn text-[14px] medium text-[#1D1D1D] text-center max-w-[72px] border-none py-1  w-[72px] h-[24px]"
        />
        {loading && <Spinner />}
      </div>
      <div className={``}>
        <div className="product-info-price">
          {product?.offer_price ? (
            <>
              <div className="flex-col">
                <div className="flex-row">
                  <div className="product-old-price text-[18px] text-[#C4C2C2] regular">
                    {RoundPrice({
                      num: product.price,
                      rate: currency?.exchange_rate,
                      points:
                        (decimal_point_settings &&
                          decimal_point_settings["starting-setting"]
                            ?.decimal_point_settings) ||
                        0,
                    })}
                    <svg
                      className="bottom-3"
                      xmlns="http://www.w3.org/2000/svg"
                      width="100%"
                      height="2"
                    >
                      <line
                        id="Line_1104"
                        data-name="Line 1104"
                        x2="100%"
                        transform="translate(0 1)"
                        fill="none"
                        stroke="#C4C2C2"
                        strokeWidth="2"
                      />
                    </svg>
                  </div>
                  <div className="product-new-price text-[18px] bold">
                    {RoundPrice({
                      num: product?.offer_price,
                      rate: currency.exchange_rate,
                      points:
                        (decimal_point_settings &&
                          decimal_point_settings["starting-setting"]
                            ?.decimal_point_settings) ||
                        0,
                    })}
                  </div>
                  <div className="product-currency text-[8px] light text-[#1D1D1D]">
                    {currency?.symbol}
                  </div>
                </div>
                <div className="flex-row">
                  <SavedIcon />
                  <span className="text-[8px] text-[#388CFF]  need-row-rev mx-[4px]">
                    {translate("Saved")}{" "}
                    <span className="bold">
                      {parseInt(
                        (
                          ((product.price - product?.offer_price) /
                            product.price) *
                          100
                        ).toString()
                      )}
                      %
                    </span>
                  </span>
                </div>
              </div>
            </>
          ) : (
            <>
              <div className="product-new-price text-[14px] light text-[#1D1D1D]">
                {RoundPrice({
                  num: product.price,
                  rate: currency.exchange_rate,
                  points:
                    (decimal_point_settings &&
                      decimal_point_settings["starting-setting"]
                        ?.decimal_point_settings) ||
                    0,
                })}
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

import { AxiosGet, AxiosPost } from "utils/AxiosApi";
import { _isStoreLastJson } from "utils/functions";
import { store } from "store";
import { GetAddressListApi, GetWalletApi, PlaceOrderApi } from "models/Api";

class OrderService {
  async PlaceOrder() {
    let addressId = store.getState().cart.addressLists[0]?.id;
    try {
      store.dispatch({ type: "ORDER-LOADING", payload: true });
      let data: PlaceOrderApi = await AxiosGet({
        url:
          process.env.NEXT_PUBLIC_BACKEND_URL +
          `/customer/order/wallet-pay?order_note=order note&address_id=${addressId}`,
        title: "pay Wallet",
      });
      store.dispatch({ type: "ORDER-SUCCESS", payload: data });
      store.dispatch({ type: "ORDER-LOADING", payload: false });
    } catch (error) {
      store.dispatch({ type: "ORDER-LOADING", payload: false });
    }
  }
  async GetWallet() {
    try {
      store.dispatch({ type: "ORDER-LOADING", payload: true });
      let data: GetWalletApi = await AxiosGet({
        url:
          process.env.NEXT_PUBLIC_BACKEND_URL +
          "/customer/wallet/list?limit=10&offset=1",
        title: "Get Wallet",
      });
      store.dispatch({ type: "WALLET-USER", payload: data });
      store.dispatch({ type: "ORDER-LOADING", payload: false });
    } catch (error) {
      store.dispatch({ type: "ORDER-LOADING", payload: false });
    }
  }
  async GetAddressList() {
    try {
      store.dispatch({ type: "ORDER-LOADING", payload: true });
      let data: GetAddressListApi = await AxiosGet({
        url: process.env.NEXT_PUBLIC_BACKEND_URL + "/customer/address/list",
        title: "Get Address List",
      });

      store.dispatch({ type: "GET-ADRRESS-LIST", payload: data });
      store.dispatch({ type: "ORDER-LOADING", payload: false });
    } catch (error) {
      store.dispatch({ type: "ORDER-LOADING", payload: false });
    }
  }
  async AddAddressList({ address, callback }) {
    let body = {
      latitude: address.location.latitude,
      longitude: address.location.longitude,
      address: address.address,
      address_detail: address.address_detail,
      country: address?.Country?.name,
      city: address.region_details.city,
      province: address.region_details.province,
      town: address.region_details.town,
      street: address.region_details.street,
      building: address.region_details.building,
      // zip: "123123",
      contact_person_name: address.contact_info.contact_person_name,
      phone: address.contact_info.phone,
      alternative_phone: address.contact_info.alternative_phone,
    };
    var formBody: any = [];
    for (var property in body) {
      var encodedKey = encodeURIComponent(property);
      var encodedValue = encodeURIComponent(body[property]);
      formBody.push(encodedKey + "=" + encodedValue);
    }
    formBody = formBody.join("&");
    try {
      store.dispatch({ type: "ORDER-LOADING", payload: true });
      let data = await AxiosPost({
        url: process.env.NEXT_PUBLIC_BACKEND_URL + "/customer/address/add",
        title: "Add Address",
        body: formBody,
      });
      await this.GetAddressList();
      callback();
      store.dispatch({ type: "ADD-ADRRESS-LIST", payload: data });
      store.dispatch({ type: "ORDER-LOADING", payload: false });
    } catch (error) {
      store.dispatch({ type: "ORDER-LOADING", payload: false });
    }
  }
  async UpdateAddressList({ address, callback }) {
    let body = {
      id: address.id,
      latitude: address.location.latitude,
      longitude: address.location.longitude,
      address: address.address,
      address_detail: address.address_detail,
      country: address?.Country?.name,
      city: address.region_details.city,
      province: address.region_details.province,
      town: address.region_details.town,
      street: address.region_details.street,
      building: address.region_details.building,
      zip: "123123",
      contact_person_name: address.contact_info.contact_person_name,
      phone: address.contact_info.phone,
      alternative_phone: address.contact_info.alternative_phone,
    };
    var formBody: any = [];
    for (var property in body) {
      var encodedKey = encodeURIComponent(property);
      var encodedValue = encodeURIComponent(body[property]);
      formBody.push(encodedKey + "=" + encodedValue);
    }
    formBody = formBody.join("&");
    try {
      store.dispatch({ type: "ORDER-LOADING", payload: true });
      let data = await AxiosPost({
        url: process.env.NEXT_PUBLIC_BACKEND_URL + "/customer/address/update",
        title: "Update Address",
        body: formBody,
      });
      callback();

      store.dispatch({ type: "ORDER-LOADING", payload: false });
    } catch (error) {
      store.dispatch({ type: "ORDER-LOADING", payload: false });
    }
  }
  async DeleteAddressList({ address }) {
    try {
      store.dispatch({ type: "ORDER-LOADING", payload: true });
      let data = await AxiosPost({
        url:
          process.env.NEXT_PUBLIC_BACKEND_URL +
          `/customer/address/delete?address_id=${address}`,
        title: "Delete Address",
        body: "",
        hasMessageOnly: true,
      });

      store.dispatch({ type: "ORDER-LOADING", payload: false });
    } catch (error) {
      store.dispatch({ type: "ORDER-LOADING", payload: false });
    }
  }
}
