const CountryLabel = () => {
  const { lang } = useParams();
  // @ts-ignore
  let country = lang.split("-")[0];
  country = {
    name: allCountries.filter((s) => s.iso2 === country)[0]?.name,
    iso: country,
  };
  const dispatch = useDispatch();
  useEffect(() => {
    dispatch({
      type: "set-address-details",
      payload: { Country: { name: country?.name, code: country.iso } },
    });
  }, []);
  return (
    <div
