const OrderButtons = ({ orderLoading, setNext }) => {
  const cart = useSelector((state: StateInterface) => state.cart);
  const currency_symbol = useSelector(
    (state: StateInterface) => state.homepage.currency
  );
  const orderData = useSelector(
    (state: StateInterface) => state.cart.orderData
  );

  const address = useSelector(
    (state: StateInterface) => state.cart.addressLists
  );
  const shake = (v) => {
    if (document.querySelector(`.${v}`)) {
      document.querySelector(`.${v}`).scrollIntoView({ block: "end" });
      document.querySelector(`.${v}`).classList.add("shake-anim");
      setTimeout(() => {
        document.querySelector(`.${v}`).classList.remove("shake-anim");
      }, 1300);
    }
  };
  const wallet = useSelector((state: StateInterface) => state.cart.wallet);
  const totalBalance = () => {
    let val = 0;
    orderData.payment.map((s) => {
      val += s.balance;
    });
    return val;
  };
  const isBalanceEnough = () => {
    return totalBalance() >= cart.total_cash;
  };
  const isValid = () => {
    if (
      address &&
      address[0]?.id &&
      orderData.payment.length > 0 &&
      isBalanceEnough()
    ) {
      return true;
    } else {
      return false;
    }
  };
  const Validate = () => {
    if (!isBalanceEnough()) {
      shake("payment-valid-border");
      alert(translateFunction("Your Balance Not meet purchase value"));
    }
    if (!address[0]?.id) {
      shake("address-valid-border");
    }
    if (orderData.payment?.length === 0) {
      shake("payment-valid-border");
    }
  };
  return (
    <div className="absolute flex-col items-center payment-order-bottom left-0 w-full">
      <div
        style={{
          boxShadow: "0px -3px 20px #0000001a",
        }}
        className={` ${
          orderLoading && "opacity-55"
        }  text-center  left-0 w-full h-[100px] bg-[#fff] px-[20px] pt-[12px]`}
      >
        <div
          onClick={() => {
            Validate();
            if (isValid() && !orderLoading) {
              setNext();
            }
          }}
          className={` ${
            orderData.loading && "opacity-65 scale-95"
          } w-full text-center  justify-center cursor-pointer flex-col items-center h-[70px] ${
            isValid() ? "bg-[#346BFF]" : "bg-[#C4C2C2]"
          } text-[#FEFEFE] text-[18px] medium rounded-[20px]`}
        >
          <span>{translateFunction("Confirm Shipping & Payment")}</span>
          <span
            className={`text-[#FEFEFE] text-[14px] medium ${
              GetAppLanguage() === "ar" && "dir-rtl"
            } `}
          >
            {cart.cart.length} {translateFunction("items")} {cart.total_cash}{" "}
            {currency_symbol?.symbol}
          </span>
        </div>
      </div>
    </div>
  );
};

"use client";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import { useEffect, useRef, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { expandView, normalizeView, Sendevent } from "utils/functions";
import CartContainer from ".";
import home from "services/home";
import { Swiper, SwiperSlide } from "swiper/react";
import OrdersPage from "./OrdersPage";
import { Swiper as SwiperType } from "node_modules/swiper/types";
const CartProvider = () => {
  const dispatch = useDispatch();
  const pathname = usePathname();
  const router = useRouter();

  const searchParams = useSearchParams();
  const filterEnabled = useSelector(
    (state: StateInterface) => state.listing.filterEnabled
  );
  const enableCart = (s) => {
    dispatch({ type: "AddToCartOptionDisable", payload: false });
    window.history.pushState({ isPopup: true }, "open Cart");
    dispatch({ type: "ENABLE-CART", payload: s });
    if (s) {
      const newParams = new URLSearchParams(searchParams);
      newParams.set("cart", "true");
      // Use router.push with pathname and updated query
      // @ts-expect-error 'shallow' does not exist in type 'NavigateOptions'
      router.push(`${pathname}?${newParams.toString()}`, { shallow: true });
    } else {
      const newParams = new URLSearchParams(searchParams);
      newParams.delete("cart");

      // Use router.push with pathname and updated query
      // @ts-expect-error 'shallow' does not exist in type 'NavigateOptions'

      router.push(`${pathname}?${newParams.toString()}`, { shallow: true });
    }
  };
  useEffect(() => {
    setTimeout(() => {
      home.getClientData();
    }, 10);
    window.addEventListener("popstate", (event) => {
      if (event.state?.isPopup) {
        dispatch({ type: "STORY-SELECTED", payload: null });
        dispatch({ type: "ENABLE-CART", payload: false });
        dispatch({ type: "LOGIN-OPEN", payload: false });
        dispatch({ type: "CHAT-OPEN", payload: false });
        dispatch({ type: "ENABLE-SEARCH", payload: false });
      }
    });
    window.addEventListener("scroll", function (e) {
      if (!filterEnabled) {
        if (window.scrollY > 66) {
          expandView({ filter: false });
        } else {
          normalizeView();
        }
      }
    });
  }, []);

  useEffect(() => {
    if (searchParams.get("cart")) {
      enableCart(true);
    }
  }, []);
  const cartEnable = useSelector((state: StateInterface) => state.cart.enable);
  const showMessage = useSelector(
    (state: StateInterface) => state.homepage.showMessage
  );

  return (
    <>
      {/* {showMessage && <ShowMessageAuth />} */}
      {cartEnable ? <StepSlider enableCart={(e) => enableCart(e)} /> : <></>}
    </>
  );
};
export default CartProvider;
export const StepSlider = ({ enableCart }) => {
  const [step, setStep] = useState(0);
  const ref = useRef<SwiperType | null>();
  return (
    <div className="w-full h-[100vh] fixed z-[9999999999] cart-provider">
      {" "}
      <Swiper
        initialSlide={step}
        navigation={false}
        keyboard={{
          enabled: false,
        }}
        draggable={false}
        className="w-full h-full"
        wrapperClass="flex flex-row"
        noSwiping={false}
        allowTouchMove={false}
        slidesPerView={1}
        onInit={(swiper) => {
          ref.current = swiper;
        }}
      >
        <SwiperSlide className="w-full h-full cart-widget">
          <CartContainer
            toOrders={() => {
              ref.current.slideNext();
              setStep(1);
            }}
            close={() => {
              Sendevent({
                event: "button_clicked",
                value: "appbar_backicon_button",
              });
              enableCart(false);
            }}
          />
        </SwiperSlide>
        <SwiperSlide className="w-full h-full cart-widget">
          {({ isActive }) =>
            isActive ? (
              <>
                <OrdersPage
                  setStep={(e) => {
                    setStep(0);
                    ref.current.slidePrev();
                  }}
                />
              </>
            ) : (
              <></>
            )
          }
        </SwiperSlide>
      </Swiper>
    </div>
  );
};

