          <BuyButton
            buy={(e) => {
              // @ts-ignore

              addToCart();
              setTimeout(() => {
                if (document.querySelector("#nprogress"))
                  // @ts-ignore
                  document.querySelector("#nprogress").style.opacity = "0";
              }, 1000);
            }}
          />
        </div>
      </NextLink>
    </div>
  );
